from pathlib import Path

policy = r'''import crypto from 'node:crypto';
import { Firestore } from '@google-cloud/firestore';

const db=new Firestore({ignoreUndefinedProperties:true});
const audit=db.collection('fxga_policy_forecast_audit');
const ACTIONS=['hike','hold','cut'];
export const POLICY_LEAD_BUCKETS=[
  {id:'early-45d',label:'14–45 days',targetHours:1080,minExclusiveHours:336,maxHours:1080},
  {id:'14d',label:'7–14 days',targetHours:336,minExclusiveHours:168,maxHours:336},
  {id:'7d',label:'1–7 days',targetHours:168,minExclusiveHours:24,maxHours:168},
  {id:'24h',label:'6–24 hours',targetHours:24,minExclusiveHours:6,maxHours:24},
  {id:'final',label:'Final ≤6 hours',targetHours:6,minExclusiveHours:0,maxHours:6},
];
const clamp=(v,min=0,max=1)=>Math.max(min,Math.min(max,Number.isFinite(Number(v))?Number(v):0));
const mean=xs=>xs.length?xs.reduce((a,b)=>a+b,0)/xs.length:null;
function idFor(currency,eventId,leadBucket='legacy'){return crypto.createHash('sha256').update(`${currency}|${eventId}|${leadBucket}`).digest('hex');}
function rateNumber(value){if(typeof value==='number'&&Number.isFinite(value))return value;if(value==null)return null;const text=String(value).replace(/,/g,'').replace(/%/g,'').trim(),match=text.match(/[+-]?\d*\.?\d+/);if(!match)return null;const n=Number(match[0]);return Number.isFinite(n)?n:null;}
function normalizeProbabilities(input={}){const raw=ACTIONS.map(id=>Math.max(0,Number(input?.[id]||0))),total=raw.reduce((a,b)=>a+b,0);if(total<=0)return {hike:1/3,hold:1/3,cut:1/3};return Object.fromEntries(ACTIONS.map((id,i)=>[id,raw[i]/total]));}
function outcomeForEvent(event){const actual=rateNumber(event?.actual),previous=rateNumber(event?.revised??event?.previous);if(actual==null||previous==null)return null;const tolerance=Math.max(1e-8,Math.abs(previous)*1e-6),delta=actual-previous,action=Math.abs(delta)<=tolerance?'hold':delta>0?'hike':'cut';return {action,actual,previous,delta};}
function scoreForecast(probabilities,outcome){const p=normalizeProbabilities(probabilities),target={hike:outcome.action==='hike'?1:0,hold:outcome.action==='hold'?1:0,cut:outcome.action==='cut'?1:0},brier=ACTIONS.reduce((s,id)=>s+(p[id]-target[id])**2,0)/2,assigned=Math.max(1e-6,p[outcome.action]),logLoss=-Math.log(assigned),topAction=ACTIONS.reduce((best,id)=>p[id]>p[best]?id:best,'hike');return {probabilities:p,assignedProbability:assigned,brier,logLoss,topAction,topCorrect:topAction===outcome.action};}
export function bucketForLeadHours(value){const h=Number(value);if(!Number.isFinite(h)||h<0||h>1080)return null;if(h>336)return POLICY_LEAD_BUCKETS[0];if(h>168)return POLICY_LEAD_BUCKETS[1];if(h>24)return POLICY_LEAD_BUCKETS[2];if(h>6)return POLICY_LEAD_BUCKETS[3];return POLICY_LEAD_BUCKETS[4];}
function leadHoursForRow(row){if(Number.isFinite(Number(row?.leadHours)))return Number(row.leadHours);const release=Date.parse(row?.releaseAt||''),frozen=Date.parse(row?.frozenAt||'');return Number.isFinite(release)&&Number.isFinite(frozen)?Math.max(0,(release-frozen)/3600000):null;}
export function enrichLeadMetadata(row){const leadHours=leadHoursForRow(row),bucket=row?.leadBucket?POLICY_LEAD_BUCKETS.find(x=>x.id===row.leadBucket)||null:bucketForLeadHours(leadHours);return {...row,leadHours:leadHours==null?null:Number(leadHours.toFixed(3)),derivedLeadBucket:bucket?.id||row?.leadBucket||'outside-window',derivedLeadBucketLabel:bucket?.label||row?.leadBucketLabel||'Outside lead windows'};}
function summarizeRows(rows){const enriched=rows.map(enrichLeadMetadata),scored=enriched.filter(x=>x.scored&&Number.isFinite(Number(x.brier))),pending=enriched.length-scored.length,avgBrier=mean(scored.map(x=>Number(x.brier))),avgLogLoss=mean(scored.map(x=>Number(x.logLoss))),accuracy=scored.length?scored.filter(x=>x.topCorrect).length/scored.length:null,brierSkill=avgBrier==null?null:1-avgBrier/(1/3),sampleConfidence=scored.length/(scored.length+12),status=scored.length<5?'building':brierSkill!=null&&brierSkill>.12?'calibrating-well':brierSkill!=null&&brierSkill<-.12?'needs-recalibration':'mixed',leadValues=enriched.map(x=>x.leadHours).filter(Number.isFinite);return {frozen:enriched.length,uniqueDecisions:new Set(enriched.map(x=>x.eventId).filter(Boolean)).size,scored:scored.length,pending,topActionAccuracy:accuracy==null?null:Number(accuracy.toFixed(4)),averageBrier:avgBrier==null?null:Number(avgBrier.toFixed(5)),averageLogLoss:avgLogLoss==null?null:Number(avgLogLoss.toFixed(5)),brierSkillVsUniform:brierSkill==null?null:Number(brierSkill.toFixed(4)),sampleConfidence:Number(sampleConfidence.toFixed(4)),averageLeadHours:leadValues.length?Number(mean(leadValues).toFixed(2)):null,status};}
function pairedLeadComparison(rows,fromBucket,toBucket){const enriched=rows.map(enrichLeadMetadata).filter(x=>x.scored&&Number.isFinite(Number(x.brier))),from=new Map(enriched.filter(x=>x.derivedLeadBucket===fromBucket).map(x=>[x.eventId,x])),to=new Map(enriched.filter(x=>x.derivedLeadBucket===toBucket).map(x=>[x.eventId,x])),pairs=[];for(const [eventId,a] of from){const b=to.get(eventId);if(!b)continue;pairs.push({eventId,currency:b.currency,brierImprovement:Number((Number(a.brier)-Number(b.brier)).toFixed(6)),logLossImprovement:Number((Number(a.logLoss)-Number(b.logLoss)).toFixed(6))});}const brier=mean(pairs.map(x=>x.brierImprovement)),loss=mean(pairs.map(x=>x.logLossImprovement)),status=pairs.length<3?'building':brier>.02?'improving':brier<-.02?'worsening':'mixed';return {fromBucket,toBucket,pairs:pairs.length,averageBrierImprovement:brier==null?null:Number(brier.toFixed(5)),averageLogLossImprovement:loss==null?null:Number(loss.toFixed(5)),status};}
async function readRows(limit=800){const snap=await audit.limit(limit).get();return snap.docs.map(doc=>doc.data());}
export async function readPolicyCalibrationSummary(){const rows=await readRows(),enriched=rows.map(enrichLeadMetadata),byCurrency={},byLeadBucket={};for(const currency of new Set(enriched.map(x=>x.currency).filter(Boolean)))byCurrency[currency]=summarizeRows(enriched.filter(x=>x.currency===currency));for(const bucket of POLICY_LEAD_BUCKETS)byLeadBucket[bucket.id]=summarizeRows(enriched.filter(x=>x.derivedLeadBucket===bucket.id));const leadComparisons=POLICY_LEAD_BUCKETS.slice(0,-1).map((bucket,i)=>pairedLeadComparison(enriched,bucket.id,POLICY_LEAD_BUCKETS[i+1].id));return {generatedAt:new Date().toISOString(),auditVersion:2,leadBuckets:POLICY_LEAD_BUCKETS.map(({minExclusiveHours,maxHours,...x})=>({...x,minExclusiveHours,maxHours})),global:summarizeRows(enriched),byCurrency,byLeadBucket,leadComparisons,methodology:'Each scheduled policy decision may accumulate multiple immutable probability snapshots as it moves through non-overlapping lead windows: 14–45 days, 7–14 days, 1–7 days, 6–24 hours and final ≤6 hours. Existing legacy frozen rows are never rewritten; their lead bucket is inferred from releaseAt minus frozenAt. Missing earlier lead windows are never backfilled. Every snapshot is scored only after a real policy-rate outcome is reported. Multiclass Brier score is normalized to 0–1, log loss penalizes overconfident misses, and Brier skill is measured against a uniform 1/3-1/3-1/3 benchmark. Paired lead-time comparisons use only the same realized decision observed in both adjacent lead buckets, so improvement as a meeting approaches is not inferred from unmatched samples.'};}
export async function freezePolicyForecasts(policyResearch,events=[],now=new Date()){
  const byId=new Map((events||[]).map(event=>[event.id,event])),nowMs=now instanceof Date?now.getTime():Date.parse(now),existing=(await readRows()).map(enrichLeadMetadata),existingKeys=new Set(existing.map(x=>`${x.currency}|${x.eventId}|${x.derivedLeadBucket}`));let frozen=0,skipped=0;const frozenByLead={};
  for(const row of policyResearch?.economies||[]){const meeting=row?.nextMeeting,event=meeting?.id?byId.get(meeting.id):null,t=Date.parse(meeting?.date||'');if(!meeting?.id||!event||!Number.isFinite(t)||t<=nowMs){skipped++;continue;}const leadHours=(t-nowMs)/3600000,bucket=bucketForLeadHours(leadHours);if(!bucket){skipped++;continue;}const key=`${row.currency}|${meeting.id}|${bucket.id}`;if(existingKeys.has(key)){skipped++;continue;}const ref=audit.doc(idFor(row.currency,meeting.id,bucket.id)),snap=await ref.get();if(snap.exists){skipped++;existingKeys.add(key);continue;}const probabilities=normalizeProbabilities(row.probabilities),frozenAt=new Date().toISOString(),basis={eventId:meeting.id,currency:row.currency,releaseAt:meeting.date,leadBucket:bucket.id,leadHours:Number(leadHours.toFixed(3)),probabilities,pathPressure:row.pathPressure,expectedNetSteps:row.sequenceTree?.expectedNetSteps??null,dataPressure:row.dataPressure,reactionGap:row.reactionGap,confidence:row.confidence},snapshotHash=crypto.createHash('sha256').update(JSON.stringify(basis)).digest('hex');await ref.set({...basis,auditVersion:2,event:meeting.event,centralBank:row.centralBank,frozenAt,leadBucketLabel:bucket.label,targetLeadHours:bucket.targetHours,topPaths:(row.sequenceTree?.topPaths||[]).slice(0,8),modelGeneratedAt:policyResearch?.generatedAt||null,snapshotHash,scored:false},{merge:false});frozen++;frozenByLead[bucket.id]=(frozenByLead[bucket.id]||0)+1;existingKeys.add(key);}
  return {frozen,skipped,frozenByLead};
}
export async function scorePolicyForecasts(events=[]){
  const byId=new Map((events||[]).map(event=>[event.id,event])),pending=await audit.where('scored','==',false).limit(240).get();let scored=0;const scoredByLead={};
  for(const doc of pending.docs){const row=enrichLeadMetadata(doc.data()),event=byId.get(row.eventId),outcome=outcomeForEvent(event);if(!outcome)continue;const score=scoreForecast(row.probabilities,outcome);await doc.ref.set({scored:true,scoredAt:new Date().toISOString(),outcome,assignedProbability:Number(score.assignedProbability.toFixed(6)),brier:Number(score.brier.toFixed(6)),logLoss:Number(score.logLoss.toFixed(6)),topAction:score.topAction,topCorrect:score.topCorrect},{merge:true});scored++;scoredByLead[row.derivedLeadBucket]=(scoredByLead[row.derivedLeadBucket]||0)+1;}
  return {scored,scoredByLead,summary:await readPolicyCalibrationSummary()};
}
export const policyCalibrationMath={normalizeProbabilities,outcomeForEvent,scoreForecast,bucketForLeadHours,enrichLeadMetadata,summarizeRows,pairedLeadComparison};
'''

panel = r'''import './PolicyCalibrationPanel.css';

export type PolicyCalibrationMetric={frozen:number;uniqueDecisions?:number;scored:number;pending:number;topActionAccuracy:number|null;averageBrier:number|null;averageLogLoss:number|null;brierSkillVsUniform:number|null;sampleConfidence:number;averageLeadHours?:number|null;status:string};
type LeadBucket={id:string;label:string;targetHours:number;minExclusiveHours:number;maxHours:number};
type LeadComparison={fromBucket:string;toBucket:string;pairs:number;averageBrierImprovement:number|null;averageLogLossImprovement:number|null;status:string};
export type PolicyCalibrationResearch={generatedAt:string;auditVersion?:number;leadBuckets?:LeadBucket[];global:PolicyCalibrationMetric;byCurrency:Record<string,PolicyCalibrationMetric>;byLeadBucket?:Record<string,PolicyCalibrationMetric>;leadComparisons?:LeadComparison[];methodology:string};
const pct=(v:number|null|undefined)=>v==null?'—':`${Math.round(v*100)}%`;
const num=(v:number|null|undefined,d=3)=>v==null?'—':Number(v).toFixed(d);
const cls=(status:string)=>status==='calibrating-well'||status==='improving'?'positive':status==='needs-recalibration'||status==='worsening'?'negative':'neutral';
const label=(value:string)=>value.replaceAll('-',' ').replace(/\b\w/g,m=>m.toUpperCase());

export function PolicyCalibrationPanel({data}:{data?:PolicyCalibrationResearch|null}){
  if(!data)return null;
  const rows=Object.entries(data.byCurrency||{}).sort((a,b)=>b[1].scored-a[1].scored||b[1].frozen-a[1].frozen);
  const buckets=(data.leadBuckets||[]).map(bucket=>({bucket,metric:data.byLeadBucket?.[bucket.id]}));
  const comparisons=(data.leadComparisons||[]).filter(x=>x.pairs>0);
  return <>
    <section className="section-head policy-calibration-head"><div><span className="eyebrow">Policy Forecast Audit</span><h2>Does policy probability accuracy improve as the meeting approaches?</h2><p>Each meeting can now accumulate immutable snapshots across separate lead windows. Missing earlier windows are never backfilled, and every snapshot waits for the real rate outcome before receiving a score.</p></div></section>
    <section className="panel policy-calibration-panel">
      <div className="policy-calibration-summary">
        <div><small>Frozen snapshots</small><strong>{data.global.frozen}</strong></div>
        <div><small>Unique decisions</small><strong>{data.global.uniqueDecisions??data.global.frozen}</strong></div>
        <div><small>Scored snapshots</small><strong>{data.global.scored}</strong></div>
        <div><small>Brier skill vs uniform</small><strong className={data.global.brierSkillVsUniform!=null&&data.global.brierSkillVsUniform>0?'positive':data.global.brierSkillVsUniform!=null&&data.global.brierSkillVsUniform<0?'negative':'neutral'}>{pct(data.global.brierSkillVsUniform)}</strong></div>
      </div>

      {buckets.length>0&&<div className="policy-lead-block"><div className="policy-lead-title"><div><span className="eyebrow">Lead-Time Calibration Curve</span><h3>Immutable snapshot windows</h3></div><small>Exact lead hours are retained on every audit row</small></div><div className="policy-lead-grid">{buckets.map(({bucket,metric})=><div className="policy-lead-card" key={bucket.id}><div><strong>{bucket.label}</strong><span className={cls(metric?.status||'building')}>{label(metric?.status||'building')}</span></div><small>{metric?.scored||0} scored · {metric?.pending||0} pending · {metric?.frozen||0} frozen</small><div className="policy-lead-metrics"><span>Brier <b>{num(metric?.averageBrier)}</b></span><span>Log loss <b>{num(metric?.averageLogLoss)}</b></span><span>Accuracy <b>{pct(metric?.topActionAccuracy)}</b></span><span>Sample <b>{pct(metric?.sampleConfidence)}</b></span></div></div>)}</div></div>}

      {comparisons.length>0&&<div className="policy-lead-comparisons"><span className="eyebrow">Matched-Decision Improvement</span>{comparisons.map(row=><div key={`${row.fromBucket}-${row.toBucket}`}><strong>{label(row.fromBucket)} → {label(row.toBucket)}</strong><span className={cls(row.status)}>{row.status}</span><small>{row.pairs} matched decisions · Brier improvement {num(row.averageBrierImprovement)} · log-loss improvement {num(row.averageLogLossImprovement)}</small></div>)}</div>}

      <div className="policy-calibration-table">{rows.map(([currency,row])=><div className="policy-calibration-row" key={currency}><div><strong>{currency}</strong><small>{row.scored} scored snapshots · {row.pending} pending · {row.uniqueDecisions??row.frozen} decisions</small></div><span className={cls(row.status)}>{row.status.replaceAll('-',' ')}</span><span>Accuracy {pct(row.topActionAccuracy)}</span><span>Brier {num(row.averageBrier)}</span><span>Log loss {num(row.averageLogLoss)}</span><span>Sample {pct(row.sampleConfidence)}</span></div>)}</div>
      {!data.global.scored&&<p className="policy-calibration-building">Calibration is building from genuine frozen forecasts only. The current pending snapshots will receive scores only after their actual policy decisions are published.</p>}
      <details><summary>Scoring methodology</summary><p>{data.methodology}</p></details>
    </section>
  </>;
}
'''

css = r'''.policy-calibration-head{margin-top:30px}.policy-calibration-panel{display:grid;gap:15px}.policy-calibration-summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:9px}.policy-calibration-summary>div{padding:11px 12px;border:1px solid rgba(148,163,184,.14);border-radius:10px;background:rgba(15,23,42,.28);display:grid;gap:3px}.policy-calibration-summary small,.policy-calibration-row small{color:var(--muted);font-size:.72rem}.policy-calibration-summary strong{font-size:1.25rem;font-variant-numeric:tabular-nums}.policy-calibration-table{display:grid;gap:6px}.policy-calibration-row{display:grid;grid-template-columns:minmax(155px,1.2fr) .9fr repeat(4,.8fr);gap:8px;align-items:center;padding:10px 11px;border:1px solid rgba(148,163,184,.11);border-radius:9px}.policy-calibration-row>div{display:grid;gap:2px}.policy-calibration-row span{font-size:.78rem;font-variant-numeric:tabular-nums}.policy-calibration-building{margin:0;color:var(--muted);line-height:1.5}.policy-calibration-panel details{border-top:1px solid rgba(148,163,184,.14);padding-top:9px}.policy-calibration-panel summary{cursor:pointer}.policy-calibration-panel details p{color:var(--muted);line-height:1.55}.policy-lead-block{display:grid;gap:10px;padding:12px;border:1px solid rgba(148,163,184,.12);border-radius:11px;background:rgba(15,23,42,.18)}.policy-lead-title{display:flex;justify-content:space-between;gap:12px;align-items:end}.policy-lead-title h3{margin:2px 0 0;font-size:1rem}.policy-lead-title>small{color:var(--muted);font-size:.68rem}.policy-lead-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:7px}.policy-lead-card{display:grid;gap:7px;padding:9px;border:1px solid rgba(148,163,184,.10);border-radius:9px;background:rgba(2,6,23,.20)}.policy-lead-card>div:first-child{display:flex;justify-content:space-between;gap:6px;align-items:center}.policy-lead-card strong{font-size:.78rem}.policy-lead-card>div:first-child span{font-size:.62rem;text-transform:uppercase}.policy-lead-card>small{font-size:.66rem;color:var(--muted)}.policy-lead-metrics{display:grid;grid-template-columns:1fr 1fr;gap:4px}.policy-lead-metrics span{font-size:.65rem;color:var(--muted)}.policy-lead-metrics b{display:block;color:var(--text);font-size:.74rem;font-variant-numeric:tabular-nums}.policy-lead-comparisons{display:grid;gap:6px}.policy-lead-comparisons>div{display:grid;grid-template-columns:minmax(160px,1fr) auto minmax(220px,2fr);gap:8px;align-items:center;padding:8px 10px;border:1px solid rgba(148,163,184,.10);border-radius:8px}.policy-lead-comparisons strong{font-size:.76rem}.policy-lead-comparisons span{font-size:.68rem;text-transform:uppercase}.policy-lead-comparisons small{color:var(--muted);font-size:.7rem}@media(max-width:1100px){.policy-lead-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:900px){.policy-calibration-summary{grid-template-columns:repeat(2,minmax(0,1fr))}.policy-calibration-row{grid-template-columns:1fr 1fr}.policy-calibration-row>div{grid-column:1/-1}.policy-lead-grid{grid-template-columns:1fr 1fr}.policy-lead-comparisons>div{grid-template-columns:1fr 1fr}.policy-lead-comparisons small{grid-column:1/-1}}@media(max-width:560px){.policy-lead-grid{grid-template-columns:1fr}.policy-lead-title{align-items:start;flex-direction:column}}'''

Path('cloud-run-collector/src/policy-calibration.js').write_text(policy)
Path('src/components/PolicyCalibrationPanel.tsx').write_text(panel)
Path('src/components/PolicyCalibrationPanel.css').write_text(css)
print('v4.19 policy lead-time calibration patch applied')
